#!/usr/bin/env python3
"""Applies the native permissions and background modes the app needs to the platform folders generated by `flutter create`.
Idempotent: safe to run several times. Usage: python3 tool/configure_native.py [mobile_dir]"""
import plistlib
import re
import sys
from pathlib import Path

ANDROID_PERMISSIONS = [
    "android.permission.INTERNET",                      # not in the release manifest generated by flutter create
    "android.permission.ACCESS_NETWORK_STATE",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
    "android.permission.ACCESS_BACKGROUND_LOCATION",    # student tracking while the app is in the background (see store/ justification)
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_LOCATION",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.CAMERA",                        # QR scan (cash payments)
    "android.permission.USE_BIOMETRIC",
]
IOS_STRINGS = {
    "NSLocationWhenInUseUsageDescription": "ÉcoleManager partage ta position avec tes parents uniquement s'ils l'ont autorisé. / Your location is shared with your parents only if they allowed it.",
    "NSLocationAlwaysAndWhenInUseUsageDescription": "Pendant les heures d'école, ta position est envoyée même quand l'application est fermée, uniquement avec l'accord de tes parents. / During school hours your location is sent even in the background, only with your parents' consent.",
    "NSLocationAlwaysUsageDescription": "Suivi de position en arrière-plan avec consentement parental. / Background location with parental consent.",
    "NSCameraUsageDescription": "La caméra sert à scanner le code QR de paiement en espèces. / The camera is used to scan the cash payment QR code.",
    "NSFaceIDUsageDescription": "Déverrouillage biométrique optionnel de l'application. / Optional biometric unlock.",
}
IOS_BACKGROUND_MODES = ["location", "remote-notification"]


def patch_android(root: Path) -> bool:
    f = root / "android/app/src/main/AndroidManifest.xml"
    if not f.exists():
        return False
    xml = f.read_text(encoding="utf-8")
    missing = [p for p in ANDROID_PERMISSIONS if f'android:name="{p}"' not in xml]
    if missing:
        block = "".join(f'    <uses-permission android:name="{p}"/>\n' for p in missing)
        xml = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + block, xml, count=1)
        f.write_text(xml, encoding="utf-8")
    return True


NETWORK_CONFIG = """<?xml version="1.0" encoding="utf-8"?>
<!-- model_viewer_plus serves its viewer page from a local http server: cleartext is allowed for the device itself ONLY. Everything else stays https. -->
<network-security-config>
    <base-config cleartextTrafficPermitted="false"/>
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">localhost</domain>
        <domain includeSubdomains="false">127.0.0.1</domain>
    </domain-config>
</network-security-config>
"""
AR_QUERIES = """    <queries>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>
    </queries>
"""


def patch_android_xr(root: Path) -> bool:
    """3D/AR viewer (ARCore Scene Viewer through model_viewer_plus): local-only cleartext and the intent query needed to launch Scene Viewer."""
    f = root / "android/app/src/main/AndroidManifest.xml"
    if not f.exists():
        return False
    res = root / "android/app/src/main/res/xml"
    res.mkdir(parents=True, exist_ok=True)
    (res / "network_security_config.xml").write_text(NETWORK_CONFIG, encoding="utf-8")
    xml = f.read_text(encoding="utf-8")
    if "android:networkSecurityConfig" not in xml:
        xml = re.sub(r"<application", '<application android:networkSecurityConfig="@xml/network_security_config"', xml, count=1)
    if "<queries>" not in xml:
        xml = re.sub(r"(<manifest[^>]*>\s*\n)", lambda m: m.group(1) + AR_QUERIES, xml, count=1)
    f.write_text(xml, encoding="utf-8")
    return True


def patch_ios(root: Path) -> bool:
    f = root / "ios/Runner/Info.plist"
    if not f.exists():
        return False
    data = plistlib.loads(f.read_bytes())
    data.update(IOS_STRINGS)
    data["io.flutter.embedded_views_preview"] = True          # WebView-based 3D/AR viewer (AR Quick Look)
    modes = list(data.get("UIBackgroundModes", []))
    data["UIBackgroundModes"] = modes + [m for m in IOS_BACKGROUND_MODES if m not in modes]
    f.write_bytes(plistlib.dumps(data))
    return True


if __name__ == "__main__":
    base = Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    a, i = patch_android(base), patch_ios(base)
    if a:
        patch_android_xr(base)
    print(f"android={'patched' if a else 'absent'} ios={'patched' if i else 'absent'}")
    if not (a or i):
        sys.exit("no platform folder found: run `flutter create --platforms=android,ios .` first")
